(* [comment removed for export] *)
Definition stk (sptop : Z) (M : word -> option byte) (sp scr : Z) : Prop :=
  sp mod 16 = 0 /\ sptop - 2 ^ 23 + scr <= sp /\ sp <= sptop /\ (0x7fff80000000 <= sptop <= 2 ^ 47) /\ L5.defined M (sp - scr) scr.
