(* [comment removed for export] *)
Definition agree_on (M M' : word -> option byte) (a n : Z) : Prop :=
  forall i, a <= i < a + n -> M' (Z_to_bv 64 i) = M (Z_to_bv 64 i).

Lemma rdn_agree (M M' : word -> option byte) : forall n a, 0 <= a -> a + Z.of_nat n <= 2 ^ 64 ->
